def import_dae(suffix):
    cleanup()
    bpy.ops.wm.collada_import(filepath =
        fr"/Users/jarrett/Library/Application Support/Project Prime/SamusGun/SamusGun_{suffix}.dae")
    set_common()
    set_texture_alpha('GlowBlue_mat', 0, True)
    set_texture_alpha('GlowGreen_mat', 0, True)
    set_texture_alpha('GlowOrange_mat', 0, True)
    set_texture_alpha('GlowRed_mat', 0, True)
    set_texture_alpha('GlowYellow_mat', 0, True)
    set_texture_alpha('lambert10_mat', 31, False)
    set_back_culling('lambert10_mat')
    set_mat_color('lambert10_mat', 1, 0.7419355, 0, False, [])
    set_texture_alpha('lambert11_mat', 31, False)
    set_back_culling('lambert11_mat')
    set_mat_color('lambert11_mat', 1, 1, 1, False, [])
    bone_setup()
    anim_setup()

